using UnityEditor;
using UnityEngine;

namespace Fire3D.Unity.Editor.ContentPipeline
{
    /// <summary>HUD icons (Resources/UI/Icons, generated by Tools/UiIcons) import as crisp, mip-mapped sprites.</summary>
    public sealed class UiAssetImporter : AssetPostprocessor
    {
        private const string IconFolder = "Assets/_Fire3D/Resources/UI/Icons/";

        private void OnPreprocessTexture()
        {
            if (!assetPath.StartsWith(IconFolder))
                return;
            var t = (TextureImporter)assetImporter;
            t.textureType = TextureImporterType.Sprite;
            t.spriteImportMode = SpriteImportMode.Single;
            t.alphaIsTransparency = true;
            t.alphaSource = TextureImporterAlphaSource.FromInput;
            t.mipmapEnabled = true;
            t.filterMode = FilterMode.Trilinear;
            t.wrapMode = TextureWrapMode.Clamp;
            t.npotScale = TextureImporterNPOTScale.None;
            t.maxTextureSize = 256;
            t.textureCompression = TextureImporterCompression.Uncompressed;
            t.sRGBTexture = true;
        }
    }
}
